struct png_info_def{
/* The following are necessary for every PNG file */
png_uint_32 width;
/* valid chunk data (see PNG_INFO_ below) */
size_t rowbytes;
/* bytes needed to hold an untransformed row */
png_colorp palette;
/* array of color values (valid & PNG_INFO_PLTE) */
png_uint_16 num_palette;
/* number of transparent palette color (tRNS) */
png_byte bit_depth;
/* This is never set during write */
png_byte signature[8];
/* png_colorspace only contains 'flags' if neither GAMMA or COLORSPACE are
    * defined.  When COLORSPACE is switched on all the colorspace-defining
    * chunks should be enabled, when GAMMA is switched on all the gamma-defining
    * chunks should be enabled.  If this is not done it becomes possible to read
    * inconsistent PNG files and assign a probably incorrect interpretation to
    * the information.  (In other words, by carefully choosing which chunks to
    * recognize the system configuration can select an interpretation for PNG
    * files containing ambiguous data and this will result in inconsistent
    * behavior between different libpng builds!)
    */
png_colorspace colorspace;
/* iCCP chunk data. */
png_charp iccp_name;
/* profile name */
png_bytep iccp_profile;
/* The tEXt, and zTXt chunks contain human-readable textual data in
    * uncompressed, compressed, and optionally compressed forms, respectively.
    * The data in "text" is an array of pointers to uncompressed,
    * null-terminated C strings. Each chunk has a keyword that describes the
    * textual data contained in that chunk.  Keywords are not required to be
    * unique, and the text string may be empty.  Any number of text chunks may
    * be in an image.
    */
int num_text;
/* current size of text array */
png_textp text;
/* The tIME chunk holds the last time the displayed image data was
    * modified.  See the png_time struct for the contents of this struct.
    */
png_time mod_time;
/* The sBIT chunk specifies the number of significant high-order bits
    * in the pixel data.  Values are in the range [1, bit_depth], and are
    * only specified for the channels in the pixel data.  The contents of
    * the low-order bits is not specified.  Data is valid if
    * (valid & PNG_INFO_sBIT) is non-zero.
    */
png_color_8 sig_bit;
/* alpha values for paletted image */
png_color_16 trans_color;
/* The oFFs chunk gives the offset in "offset_unit_type" units rightwards
    * and downwards from the top-left corner of the display, page, or other
    * application-specific co-ordinate space.  See the PNG_OFFSET_ defines
    * below for the unit types.  Valid if (valid & PNG_INFO_oFFs) non-zero.
    */
png_int_32 x_offset;
/* The hIST chunk contains the relative frequency or importance of the
    * various palette entries, so that a viewer can intelligently select a
    * reduced-color palette, if required.  Data is an array of "num_palette"
    * values in the range [0,65535]. Data valid if (valid & PNG_INFO_hIST)
    * is non-zero.
    */
png_uint_16p hist;
/* Latin-1 string giving physical units */
png_charpp pcal_params;
/* Storage for unknown chunks that the library doesn't recognize. */
png_unknown_chunkp unknown_chunks;
/* Data on sPLT chunks (there may be more than one). */
png_sPLT_tp splt_palettes;
/* Memory has been allocated if (valid & PNG_ALLOCATED_INFO_ROWS)
      non-zero */
   /* Data valid if (valid & PNG_INFO_IDAT) non-zero */
png_bytepp row_pointers;
// ... methods are omitted
};

/* Three color definitions.  The order of the red, green, and blue, (and the
 * exact size) is not important, although the size of the fields need to
 * be png_byte or png_uint_16 (as defined below).
 */
struct png_color_struct{

png_byte red;
// ... methods are omitted
} png_color;

/* A colorspace is all the above plus, potentially, profile information;
 * however at present libpng does not use the profile internally so it is only
 * stored in the png_info struct (if iCCP is supported.)  The rendering intent
 * is retained here and is checked.
 *
 * The file gamma encoding information is also stored here and gamma correction
 * is done by libpng, whereas color correction must currently be done by the
 * application.
 */
struct png_colorspace{

png_fixed_point gamma;

png_xy      end_points_xy;
/* End points as chromaticities */
png_XYZ     end_points_XYZ;
/* End points as CIE XYZ colorant values */
png_uint_16 rendering_intent;
// ... methods are omitted
} png_colorspace, * PNG_RESTRICT png_colorspacerp;

/* The chromaticities of the red, green and blue colorants and the chromaticity
 * of the corresponding white point (i.e. of rgb(1.0,1.0,1.0)).
 */
struct png_xy{

png_fixed_point redx, redy;
// ... methods are omitted
} png_xy;

/* The same data as above but encoded as CIE XYZ values.  When this data comes
 * from chromaticities the sum of the Y values is assumed to be 1.0
 */
struct png_XYZ{

png_fixed_point red_X, red_Y, red_Z;
// ... methods are omitted
} png_XYZ;

/* png_text holds the contents of a text/ztxt/itxt chunk in a PNG file,
 * and whether that contents is compressed or not.  The "key" field
 * points to a regular zero-terminated C string.  The "text" fields can be a
 * regular C string, an empty string, or a NULL pointer.
 * However, the structure returned by png_get_text() will always contain
 * the "text" field as a regular zero-terminated C string (possibly
 * empty), never a NULL pointer, so it can be safely used in printf() and
 * other string-handling functions.  Note that the "itxt_length", "lang", and
 * "lang_key" members of the structure only exist when the library is built
 * with iTXt chunk support.  Prior to libpng-1.4.0 the library was built by
 * default without iTXt support. Also note that when iTXt *is* supported,
 * the "lang" and "lang_key" fields contain NULL pointers when the
 * "compression" field contains * PNG_TEXT_COMPRESSION_NONE or
 * PNG_TEXT_COMPRESSION_zTXt. Note that the "compression value" is not the
 * same as what appears in the PNG tEXt/zTXt/iTXt chunk's "compression flag"
 * which is always 0 or 1, or its "compression method" which is always 0.
 */
struct png_text_struct{

int  compression;
/* compression value:
                             -1: tEXt, none
                              0: zTXt, deflate
                              1: iTXt, none
                              2: iTXt, deflate  */
png_charp key;
/* comment, may be an empty string (ie "")
                              or a NULL pointer */
size_t text_length;
// ... methods are omitted
} png_text;

/* png_time is a way to hold the time in an machine independent way.
 * Two conversions are provided, both from time_t and struct tm.  There
 * is no portable way to convert to either of these structures, as far
 * as I know.  If you know of a portable way, send it to me.  As a side
 * note - PNG has always been Year 2000 compliant!
 */
struct png_time_struct{

png_uint_16 year;
/* full year, as in, 1995 */
png_byte month;
// ... methods are omitted
} png_time;

struct png_color_8_struct{

png_byte red;
// ... methods are omitted
